class Solution {
   public:
    int findKRotation(vector<int> &nums) {
        int left = 0;
        int right = nums.size() - 1;
        int ans = INT_MAX;
        int ansIdx = -1;

        while (left <= right) {
            int mid = left + (right - left) / 2;

            if (nums[mid] <= nums[right]) {  // Right side sorted
                if(nums[mid] < ans){
                    ansIdx = mid;
                    ans = nums[mid];
                }
                right = mid - 1;
            } else {
               if(nums[mid] < ans){
                    ansIdx = mid;
                    ans = nums[mid];
                }
                left = mid + 1;
            }
        }

        return ansIdx;
    }
};
```

